local keywordHandler = KeywordHandler:new()
local npcHandler = NpcHandler:new(keywordHandler)
NpcSystem.parseParameters(npcHandler)

function onCreatureAppear(cid)			npcHandler:onCreatureAppear(cid)			end
function onCreatureDisappear(cid)		npcHandler:onCreatureDisappear(cid)			end
function onCreatureSay(cid, type, msg)	npcHandler:onCreatureSay(cid, type, msg)	end
function onThink()						npcHandler:onThink()						end
npcHandler:setMessage(MESSAGE_GREET, '|PLAYERNAME|, good day .. or night, whatever.')
npcHandler:setMessage(MESSAGE_FAREWELL, 'Bye')
npcHandler:setMessage(MESSAGE_WALKAWAY, 'Bye')
keywordHandler:addKeyword({'humans'}, StdModule.say, {npcHandler = npcHandler, text = 'They are not cute and not intelligent.'})
keywordHandler:addKeyword({'equipment'}, StdModule.say, {npcHandler = npcHandler, text = 'If you own a good worm you need nothing else.'})
keywordHandler:addKeyword({'ferumbras'}, StdModule.say, {npcHandler = npcHandler, text = 'A true enemy of the worms.'})
keywordHandler:addKeyword({'news'}, StdModule.say, {npcHandler = npcHandler, text = 'Who needs news if the old things are still good enough?'})
keywordHandler:addKeyword({'bezil'}, StdModule.say, {npcHandler = npcHandler, text = 'Always chatting. How can someone talk that much?'})
keywordHandler:addKeyword({'jimbin'}, StdModule.say, {npcHandler = npcHandler, text = 'His tavern is too crowded and too bright for a dwarf with taste like me.'})
keywordHandler:addKeyword({'earth'}, StdModule.say, {npcHandler = npcHandler, text = 'Home of the worms, home of my people, too.'})
keywordHandler:addKeyword({'uzgod'}, StdModule.say, {npcHandler = npcHandler, text = 'We are trading now and then. Fine dwarf he is.'})
keywordHandler:addKeyword({'pyromancer'}, StdModule.say, {npcHandler = npcHandler, text = 'Hotheads.'})
keywordHandler:addKeyword({'monster'}, StdModule.say, {npcHandler = npcHandler, text = 'Unwormish creatures they are.'})
keywordHandler:addKeyword({'kazordoon'}, StdModule.say, {npcHandler = npcHandler, text = 'I like the mines best.'})
keywordHandler:addKeyword({'etzel'}, StdModule.say, {npcHandler = npcHandler, text = 'Does a worm need spells to work his kind of magic? I do neither.'})
keywordHandler:addKeyword({'durin'}, StdModule.say, {npcHandler = npcHandler, text = 'If he\'d live today he\'d be a rotwormtamer like me.'})
keywordHandler:addKeyword({'motos'}, StdModule.say, {npcHandler = npcHandler, text = 'That guy is a monster! I despise rotwormkillers.'})
keywordHandler:addKeyword({'kroox'}, StdModule.say, {npcHandler = npcHandler, text = 'Poor guy, has lost his drilling licence for drinking.'})
keywordHandler:addKeyword({'excalibug'}, StdModule.say, {npcHandler = npcHandler, text = 'Silly fairy tale.'})
keywordHandler:addKeyword({'maryza'}, StdModule.say, {npcHandler = npcHandler, text = 'Don\'t like the way she looks at my worms.'})
keywordHandler:addKeyword({'fire'}, StdModule.say, {npcHandler = npcHandler, text = 'Where earth is giving, fire is taking. That\'s the way of the elements.'})
keywordHandler:addKeyword({'tibia'}, StdModule.say, {npcHandler = npcHandler, text = 'More nice beneath this noisy green surface.'})
keywordHandler:addKeyword({'technomancer'}, StdModule.say, {npcHandler = npcHandler, text = 'GO AWAY! I heard they think of replacing worms with machines. That is an OUTRAGE!'})
keywordHandler:addKeyword({'elves'}, StdModule.say, {npcHandler = npcHandler, text = 'They are not worth to be mentioned.'})
keywordHandler:addKeyword({'0815'}, StdModule.say, {npcHandler = npcHandler, text = 'It\'s a special licence for artists. It was only used once as I sold a white worm to Frietsiek and Yor.'})
keywordHandler:addKeyword({'help'}, StdModule.say, {npcHandler = npcHandler, text = 'I am here to help the worms, not the fools.'})
keywordHandler:addKeyword({'army'}, StdModule.say, {npcHandler = npcHandler, text = 'They should remember old dwarfish rotworm tactics. Think like a worm and the battle is almost won.'})
keywordHandler:addKeyword({'time'}, StdModule.say, {npcHandler = npcHandler, text = 'Time does not matter to a dwarf who understands the ways of the worm.'})
keywordHandler:addKeyword({'emperor'}, StdModule.say, {npcHandler = npcHandler, text = 'The emperor should spend more money on rotworm husbandry.'})
keywordHandler:addKeyword({'god'}, StdModule.say, {npcHandler = npcHandler, text = 'The worm does not care about gods, why should I?'})
keywordHandler:addKeyword({'life'}, StdModule.say, {npcHandler = npcHandler, text = 'Can\'t say I like it much.'})
keywordHandler:addKeyword({'colossus'}, StdModule.say, {npcHandler = npcHandler, text = 'Never was up there to look at it.'})
keywordHandler:addKeyword({'citizen'}, StdModule.say, {npcHandler = npcHandler, text = 'Many noisy pepole down here are scaring my worms.'})
keywordHandler:addKeyword({'quest'}, StdModule.say, {npcHandler = npcHandler, text = 'What by the worm are you talking about?'})
keywordHandler:addKeyword({'minotaurs'}, StdModule.say, {npcHandler = npcHandler, text = 'They are stupid and ugly.'})
keywordHandler:addKeyword({'plant'}, StdModule.say, {npcHandler = npcHandler, text = 'Only a rotting plant is a good plant.'})
keywordHandler:addKeyword({'geomancer'}, StdModule.say, {npcHandler = npcHandler, text = 'They have an understanding of worms.'})
keywordHandler:addKeyword({'job'}, StdModule.say, {npcHandler = npcHandler, text = 'I am chief rotwormtamer of Kazordoon. I sell rotworms and buy meat and tasty, fresh rats for my worms.'})
keywordHandler:addKeyword({'duria'}, StdModule.say, {npcHandler = npcHandler, text = 'Thinks she\'s to good to talk to rotwormtamers.'})
keywordHandler:addKeyword({'worms'}, StdModule.say, {npcHandler = npcHandler, text = 'They are so cute and so intelligent.'})
keywordHandler:addKeyword({'name'}, StdModule.say, {npcHandler = npcHandler, text = 'I am Humgolf Molesight, Son of Earth, from the Molten Rock.'})
keywordHandler:addKeyword({'orcs'}, StdModule.say, {npcHandler = npcHandler, text = 'They are even more stupid and ugly than minotaurs.'})
keywordHandler:addKeyword({'gold'}, StdModule.say, {npcHandler = npcHandler, text = 'Gold is one of the things my worms can unearth.'})

local shopModule = ShopModule:new()
npcHandler:addModule(shopModule)
shopModule:addSellableItem({'sell'}, 3582, 4, 'sell')
shopModule:addSellableItem({'sell'}, 3577, 2, 'sell')
shopModule:addSellableItem({'sell'}, 3994, 2, 'sell')

npcHandler:addModule(FocusModule:new())

